});

// Check existing canvas conditions: what's in npc_id at runtime?
const helpData = SugarCube.setup.help_data || {};
const lc = helpData.locationCanvases || {};
// Find a canvas with NPC condition
let example = null;
for (const loc in lc) {
  for (const c of lc[loc]) {
    if (c.conditions && c.conditions.items) {
      const npcItem = c.conditions.items.find(i => i.type === 'trait' && i.subject === 'npc' && i.npc_id);
      if (npcItem) {
        example = {canvas: c.name, npc_id: npcItem.npc_id, item: npcItem};
        break;
      }
    }
  }
  if (example) break;
}
return JSON.stringify({example, npc_slug_map_sample: Object.keys(SugarCube.setup.npc_slug_map || {}).slice(0,5)});

